/* ------------- Arbitrary-arity constructions -------------- */

/**
 * Returns a new CompletableFuture that is completed when all of
 * the given CompletableFutures complete.  If any of the given
 * CompletableFutures complete exceptionally, then the returned
 * CompletableFuture also does so, with a CompletionException
 * holding this exception as its cause.  Otherwise, the results,
 * if any, of the given CompletableFutures are not reflected in
 * the returned CompletableFuture, but may be obtained by
 * inspecting them individually. If no CompletableFutures are
 * provided, returns a CompletableFuture completed with the value
 * {@code null}.
 *
 * <p>Among the applications of this method is to await completion
 * of a set of independent CompletableFutures before continuing a
 * program, as in: {@code CompletableFuture.allOf(c1, c2,
 * c3).join();}.
 *
 * @param cfs the CompletableFutures
 * @return a new CompletableFuture that is completed when all of the
 * given CompletableFutures complete
 * @throws NullPointerException if the array or any of its elements are
 * {@code null}
 */
public static CompletableFuture<Void> allOf(CompletableFuture<?>... cfs) {
    return andTree(cfs, 0, cfs.length - 1);
}

/**
 * Returns a new CompletableFuture that is completed when any of
 * the given CompletableFutures complete, with the same result.
 * Otherwise, if it completed exceptionally, the returned
 * CompletableFuture also does so, with a CompletionException
 * holding this exception as its cause.  If no CompletableFutures
 * are provided, returns an incomplete CompletableFuture.
 *
 * @param cfs the CompletableFutures
 * @return a new CompletableFuture that is completed with the
 * result or exception of any of the given CompletableFutures when
 * one completes
 * @throws NullPointerException if the array or any of its elements are
 * {@code null}
 */
public static CompletableFuture<Object> anyOf(CompletableFuture<?>... cfs) {
    int n; Object r;
    if ((n = cfs.length) <= 1)
        return (n == 0)
            ? new CompletableFuture<Object>()
            : uniCopyStage(cfs[0]);
    for (CompletableFuture<?> cf : cfs)
        if ((r = cf.result) != null)
            return new CompletableFuture<Object>(encodeRelay(r));
    cfs = cfs.clone();
    CompletableFuture<Object> d = new CompletableFuture<>();
    for (CompletableFuture<?> cf : cfs)
        cf.unipush(new AnyOf(d, cf, cfs));
    // If d was completed while we were adding completions, we should
    // clean the stack of any sources that may have had completions
    // pushed on their stack after d was completed.
    if (d.result != null)
        for (int i = 0, len = cfs.length; i < len; i++)
            if (cfs[i].result != null)
                for (i++; i < len; i++)
                    if (cfs[i].result == null)
                        cfs[i].cleanStack();
    return d;
}

/* ------------- Control and status methods -------------- */

/**
 * If not already completed, completes this CompletableFuture with
 * a {@link CancellationException}. Dependent CompletableFutures
 * that have not already completed will also complete
 * exceptionally, with a {@link CompletionException} caused by
 * this {@code CancellationException}.
 *
 * @param mayInterruptIfRunning this value has no effect in this
 * implementation because interrupts are not used to control
 * processing.
 *
 * @return {@code true} if this task is now cancelled
 */
public boolean cancel(boolean mayInterruptIfRunning) {
    boolean cancelled = (result == null) &&
        internalComplete(new AltResult(new CancellationException()));
    postComplete();
    return cancelled || isCancelled();
}

/**
 * Returns {@code true} if this CompletableFuture was cancelled
 * before it completed normally.
 *
 * @return {@code true} if this CompletableFuture was cancelled
 * before it completed normally
 */
public boolean isCancelled() {
    Object r;
    return ((r = result) instanceof AltResult) &&
        (((AltResult)r).ex instanceof CancellationException);
}

/**
 * Returns {@code true} if this CompletableFuture completed
 * exceptionally, in any way. Possible causes include
 * cancellation, explicit invocation of {@code
 * completeExceptionally}, and abrupt termination of a
 * CompletionStage action.
 *
 * @return {@code true} if this CompletableFuture completed
 * exceptionally
 */
public boolean isCompletedExceptionally() {
    Object r;
    return ((r = result) instanceof AltResult) && r != NIL;
}

/**
 * @since 19
 */
@Override
public State state() {
    Object r = result;
    if (r == null)
        return State.RUNNING;
    if (r != NIL && r instanceof AltResult alt) {
        if (alt.ex instanceof CancellationException)
            return State.CANCELLED;
        else
            return State.FAILED;
    }
    return State.SUCCESS;
}

/**
 * Forcibly sets or resets the value subsequently returned by
 * method {@link #get()} and related methods, whether or not
 * already completed. This method is designed for use only in
 * error recovery actions, and even in such situations may result
 * in ongoing dependent completions using established versus
 * overwritten outcomes.
 *
 * @param value the completion value
 */
public void obtrudeValue(T value) {
    result = (value == null) ? NIL : value;
    postComplete();
}

/**
 * Forcibly causes subsequent invocations of method {@link #get()}
 * and related methods to throw the given exception, whether or
 * not already completed. This method is designed for use only in
 * error recovery actions, and even in such situations may result
 * in ongoing dependent completions using established versus
 * overwritten outcomes.
 *
 * @param ex the exception
 * @throws NullPointerException if the exception is null
 */
public void obtrudeException(Throwable ex) {
    result = new AltResult(Objects.requireNonNull(ex));
    postComplete();
}

/**
 * Returns the estimated number of CompletableFutures whose
 * completions are awaiting completion of this CompletableFuture.
 * This method is designed for use in monitoring system state, not
 * for synchronization control.
 *
 * @return the number of dependent CompletableFutures
 */
public int getNumberOfDependents() {
    int count = 0;
    for (Completion p = stack; p != null; p = p.next)
        ++count;
    return count;
}

/**
 * Returns a string identifying this CompletableFuture, as well as
 * its completion state.  The state, in brackets, contains the
 * String {@code "Completed normally"} or the String {@code
 * "Completed exceptionally"}, or the String {@code "Not
 * completed"} followed by the number of CompletableFutures
 * dependent upon its completion, if any.
 *
 * @return a string identifying this CompletableFuture, as well as its state
 */
public String toString() {
    Object r = result;
    int count = 0; // avoid call to getNumberOfDependents in case disabled
    for (Completion p = stack; p != null; p = p.next)
        ++count;
    return super.toString() +
        ((r == null)
         ? ((count == 0)
            ? "[Not completed]"
            : "[Not completed, " + count + " dependents]")
         : (((r instanceof AltResult) && ((AltResult)r).ex != null)
            ? "[Completed exceptionally: " + ((AltResult)r).ex.getClass().getName() + "]"
            : "[Completed normally]"));
}

