      "location": {
        "type": "geo_shape"
      }
    }
  }
}
```
{% include copy-curl.html %}

Next, index some documents into the `national_parks` index:

```json
PUT /national_parks/_doc/1
{
  "name": "Yellowstone National Park",
  "location":
