  "size": 0,
  "aggs": {
    "comments": {
      "nested": { "path": "comments" },
      "aggs": {
        "replies": {
          "nested": { "path": "comments.replies" },
          "aggs": {
            "reply_authors": {
              "terms": { "field": "comments.replies.author" },
